const assert = require('assert');
const { evaluate } = require('./s5_expr.js');

try {
  assert.strictEqual(evaluate('1 + 2'), 3);
  assert.strictEqual(evaluate('3 - 4'), -1);
  assert.strictEqual(evaluate('5 * 6'), 30);
