function parseExpression(expr) {
  let { value, rest } = parseTerm(expr);

  while (rest.length > 0) {
    const op = rest[0];
    rest = rest.slice(1);

    if (op === '+' || op === '-') {
      const { value: nextValue, rest: nextRest } = parseTerm(rest);
      switch (op) {
        case '+':
          value += nextValue;
          break;
        case '-':
          value -= nextValue;
          break;
      }
      rest = nextRest;
    } else {
      throw new Error('Invalid operator');
    }
  }

  return value;
}

function parseTerm(expr) {
  let { value, rest } = parseFactor(expr);

  while (rest.length > 0) {
    const op = rest[0];
    rest = rest.slice(1);

    if (op === '*' || op === '/') {
      const { value: nextValue, rest: nextRest } = parseFactor(rest);
      switch (op) {
        case '*':
          value *= nextValue;
          break;
        case '/':
          if (nextValue === 0) {
            throw new Error('Division by zero');
          }
          value /= nextValue;
          break;
      }
      rest = nextRest;
    } else {
      throw new Error('Invalid operator');
    }
  }

  return value;
}

function parseFactor(expr) {
