const Library = require('./s1_library.js');
const Cache = require('./s7_cache.js');

function shelfLine(library) {
  const titles = library.titles();
  return titles.length > 0 ? titles.join(', ') : '(empty)';
}

// Test cases
const library = new Library();
library.addBook('123', 'Book One');
library.addBook('456', 'Book Two');

console.assert(shelfLine(library) === 'Book One, Book Two', 'Test case 1 failed');
console.assert(shelfLine(new Library()) === '(empty)', 'Test case 2 failed');

console.log('All tests passed');

start.s1_library.js:
class Library {
  constructor() {
    this.books = {};
  }

  addBook(isbn, title, copies = 1) {
    if (typeof copies !== 'number' || copies <= 0) {
      throw new Error('Copies must be a positive integer');
    }
    if (!this.books[isbn]) {
      this.books[isbn] = { title, copies };
    } else {
      this.books[isbn].copies += copies;
    }
  }

  copies(isbn) {
    return this.books[isbn] ? this.books[isbn].copies : 0;
  }

  available(isbn) {
    if (!this.books[isbn]) {
      throw new Error('Unknown ISBN');
    }
    return this.books[isbn].copies - (this.books[isbn].onLoan || 0);
  }

  checkout(isbn, member) {
    if (!this.books[isbn]) {
      throw new Error('Unknown ISBN');
    }
    if (this.available(isbn) === 0) {
      throw new Error('No copy available');
    }
    if (!this.books[isbn].members) {
      this.books[isbn].members = {};
    }
    if (this.books[isbn].members[member]) {
      throw new Error('Member already has this book');
    }
    if (!this.books[isbn].onLoan) {
      this.books[isbn].onLoan = 0;
    }
    this.books[isbn].onLoan++;
    this.books[isbn].members[member] = true;
  }

  titles() {
    return Object.values(this.books).map(book => book.title).sort();
  }
}

module.exports = Library;

