        case '*':
          value *= nextValue;
          break;
        case '/':
          if (nextValue === 0) {
            throw new Error('Division by zero');
          }
          value /= nextValue;
          break;
      }
      rest = nextRest;
    } else {
      throw new Error('Invalid operator');
    }
  }

  return value;
}

function parseFactor(expr) {
