class Graph:
    def __init__(self):
        self._nodes = set()
        self.edges = {}

    def add_node(self, n):
        self._nodes.add(n)

    def add_edge(self, a, b, weight=1):
        if a not in self._nodes or b not in self._nodes:
            raise ValueError("Both nodes must exist in the graph")
        self.edges[a].append((b, weight))
        self.edges[b].append((a, weight))

    def nodes(self):
        return self._nodes

    def neighbors(self, a):
        if a not in self._nodes:
            raise KeyError(f"Node {a} is unknown")
        return [neighbor for neighbor, _ in self.edges[a]]

    def bfs(self, start):
        if start not in self._nodes:
            raise KeyError(f"Start node {start} is unknown")
        
        visited = set()
        queue = deque([start])
        result = []

        while queue:
            node = queue.popleft()
            if node not in visited:
                visited.add(node)
                result.append(node)
                neighbors = sorted(self.neighbors(node))
