def parse_line(line):
    parts = line.split()
    if len(parts) != 10:
        raise ValueError("Invalid line format")
    
    ip = parts[0]
    time = parts[3][1:-1]
    request = parts[5][1:-1]
    method, path = request.split()
    status = int(parts[8])
    bytes_str = parts[9]
    bytes_ = int(bytes_str) if bytes_str != "-" else 0
    seconds = float(parts[7])
    
    return {
        "ip": ip,
        "time": time,
        "method": method,
        "path": path,
        "status": status,
        "bytes": bytes_,
        "seconds": seconds
    }

if __name__ == "__main__":
    # Test cases
    test_line = '127.0.0.1 - - [10/Oct/2023:13:55:36 +0000] "GET /index.html HTTP/1.1" 200 2326 0.045'
    expected_output = {
