def parse_log(text):
    lines = text.splitlines()
    parsed_logs = []
    malformed_lines = []

    for i, line in enumerate(lines, start=1):
        try:
            parsed_logs.append(parse_line(line))
        except ValueError:
            malformed_lines.append(i)

    return parsed_logs, malformed_lines
def status_counts(entries):
    counts = {}
    for entry in entries:
        status = entry.split()[1]
        if status in counts:
            counts[status] += 1
        else:
            counts[status] = 1
    return counts

def error_rate(entries):
    if not entries:
        return 0.0
    error_count = sum(1 for entry in entries if int(entry.split()[1]) >= 500)
    return round(error_count / len(entries), 4)

def bad_lines(text):
    lines = text.splitlines()
    malformed_lines = []

    for i, line in enumerate(lines, start=1):
        if not line.strip():
            continue
        try:
            parse_line(line)
        except ValueError:
            malformed_lines.append(i)

    return malformed_lines

