        const row = [];
        for (let j = 0; j < x.rows[0].length; j++) {
          let sum = 0;
          for (let k = 0; k < this.rows[0].length; k++) {
            sum += this.rows[i][k] * x.rows[k][j];
          }
          row.push(sum);
        }
        result.push(row);
      }
      return new Matrix(result);
    } else {
      throw new Error("Invalid argument type");
    }
