function evaluate(expr, vars = {}) {
  const tokens = tokenize(expr);
  const ast = parse(tokens);
  return evaluateAST(ast, vars);
}

function evaluateAST(ast, vars) {
  switch (ast.type) {
    case 'number':
      return ast.value;
    case 'variable':
      if (vars.hasOwnProperty(ast.name)) {
        return vars[ast.name];
      } else {
