    const op = rest[0];
    rest = rest.slice(1);

    if (op === '*' || op === '/') {
      const { value: nextValue, rest: nextRest } = parseFactor(rest);
      switch (op) {
        case '*':
          value *= nextValue;
          break;
        case '/':
