    rest = rest.slice(1);

    if (op === '+' || op === '-') {
      const { value: nextValue, rest: nextRest } = parseTerm(rest);
      switch (op) {
        case '+':
          value += nextValue;
          break;
        case '-':
          value -= nextValue;
          break;
      }
      rest = nextRest;
    } else {
      throw new Error('Invalid operator');
    }
  }

