def parse_line(line):
    parts = line.split()
    if len(parts) != 10:
        raise ValueError("Invalid line format")
    
    ip = parts[0]
    time = parts[3][1:-1]
    request = parts[5][1:-1]
    method, path = request.split()
    status = int(parts[8])
    size = int(parts[9])
    
    return {
        'timestamp': time,
        'method': method,
        'path': path,
        'status': status,
        'size': size
    }
    status = int(parts[8])
    bytes_str = parts[9]
    bytes_ = int(bytes_str) if bytes_str != "-" else 0
    seconds = float(parts[7])
    
    return {
        "ip": ip,
        "time": time,
        "method": method,
        "path": path,
        "status": status,
        "bytes": bytes_,
        "seconds": seconds
    }

if __name__ == "__main__":
    # Test cases
    test_line = '127.0.0.1 - - [10/Oct/2023:13:55:36 +0000] "GET /index.html HTTP/1.1" 200 2326 0.045'
    expected_output = {
        "ip": "127.0.0.1",
        "time": "10/Oct/2023:13:55:36 +0000",
        "method": "GET",
        "path": "/index.html",
        "status": 200,
        "bytes": 2326,
        "seconds": 0.045
    }
    assert parse_line(test_line) == expected_output, "Test case failed"

    # Add more test cases as needed
def parse_log(text):
    lines = text.splitlines()
    parsed_logs = []
    malformed_lines = []

    for i, line in enumerate(lines, start=1):
        try:
            parsed_logs.append(parse_line(line))
        except ValueError:
            malformed_lines.append(i)

    return parsed_logs, malformed_lines
def status_counts(entries):
    counts = {}
    for entry in entries:
        status = entry.split()[1]
        if status in counts:
            counts[status] += 1
        else:
            counts[status] = 1
    return counts

def error_rate(entries):
    if not entries:
        return 0.0
    error_count = sum(1 for entry in entries if int(entry.split()[1]) >= 500)
    return round(error_count / len(entries), 4)

def top_paths(entries, n=3):
    from urllib.parse import urlparse
    from collections import Counter

    path_counts = Counter()

    for entry in entries:
        path = urlparse(entry['path']).path
        path_counts[path] += 1

    return path_counts.most_common(n)

def percentile(entries, p):
    if not 0 < p <= 100:
        raise ValueError("p must be between 0 and 100")
    if not entries:
        raise ValueError("entries must not be empty")
    
    sorted_entries = sorted(entries)
    index = int(len(sorted_entries) * (p / 100))
    return sorted_entries[index]

def bad_lines(text):
    lines = text.splitlines()
    malformed_lines = []

    for i, line in enumerate(lines, start=1):
        if not line.strip():
            continue
        try:
            parse_line(line)
        except ValueError:
            malformed_lines.append(i)

    return malformed_lines

