        self.edges = {}
        self.visited = {}
        self.rec_stack = set()

    def add_node(self, n):
        self.nodes.add(n)

    def add_edge(self, a, b, weight=1):
        if a in self.nodes and b in self.nodes:
            self.edges[(a, b)] = weight
            self.nodes.add(b)
            self.nodes.add(a)

    def nodes(self):
        return list(self.nodes)

    def neighbors(self, a):
        return self.edges.get(a, [])

    def bfs(self, start):
        visited = set()
        queue = [start]
        while queue:
            node = queue.pop(0)
            if node not in visited:
                visited.add(node)
                queue.extend(self.neighbors(node))
        return visited

