setTimeout(() => {
  console.log('After 2 seconds:', cache.peek('key1'), cache.peek('key2')); // Should print: undefined value2
}, 2000);

setTimeout(() => {
  console.log('After 3 seconds:', cache.peek('key1'), cache.peek('key2')); // Should print: undefined value2
}, 3000);

