function evaluateAST(ast, vars) {
  switch (ast.type) {
    case 'number':
      return ast.value;
    case 'variable':
      if (vars.hasOwnProperty(ast.name)) {
        return vars[ast.name];
      } else {
        throw new Error(`Unknown variable: ${ast.name}`);
