    case 'binary':
      const left = evaluateAST(ast.left, vars);
      const right = evaluateAST(ast.right, vars);
      switch (ast.operator) {
        case '+': return left + right;
        case '-': return left - right;
        case '*': return left * right;
        case '/': return left / right;
        case '%': return left % right;
