    }
    let det = 0;
    for (let i = 0; i < this.cols; i++) {
      const subMatrix = new Matrix(this.rows - 1, this.cols - 1);
      for (let j = 1; j < this.rows; j++) {
        let col = 0;
        for (let k = 0; k < this.cols; k++) {
          if (k === i) continue;
          subMatrix.data[j - 1][col++] = this.data[j][k];
        }
      }
      det += (i % 2 === 0 ? 1 : -1) * this.data[0][i] * subMatrix.determinant();
    }
    return det;
  }
