            self.add_node(a)
        if b not in self.nodes:
            self.add_node(b)
        self.edges[(a, b)] = weight

    def nodes(self):
        return sorted(self.nodes)

    def neighbors(self, a):
        if a not in self.nodes:
            return []
        return sorted([(b, self.edges[(a, b)]) for b in self.nodes if (a, b) in self.edges])

