class Graph:
    def __init__(self):
        self.nodes = set()
        self.edges = {}
        self.visited = {}
        self.rec_stack = set()

    def remove_node(self, n):
        if n not in self.nodes:
            raise KeyError("Unknown node")
        self.nodes.remove(n)
        edges_to_remove = [edge for edge in self.edges if n in edge]
        for edge in edges_to_remove:
            del self.edges[edge]

    def add_node(self, n):
        self.nodes.add(n)

    def add_edge(self, a, b, weight=1):
        if a in self.nodes and b in self.nodes:
            self.edges[(a, b)] = weight
            self.nodes.add(b)
            self.nodes.add(a)

    def nodes(self):
        return list(self.nodes)

    def neighbors(self, a):
        return self.edges.get(a, [])

    def bfs(self, start):
        visited = set()
        queue = [start]
        while queue:
            node = queue.pop(0)
            if node not in visited:
                visited.add(node)
                queue.extend(self.neighbors(node))
        return visited

    def shortest_path(self, a, b):
        if a not in self.nodes or b not in self.nodes:
            raise KeyError("Unknown node")

        if a == b:
            return (0, [a])

        import heapq
        priority_queue = [(0, [a])]
        visited = set()

        while priority_queue:
            cost, path = heapq.heappop(priority_queue)
            node = path[-1]

            if node in visited:
                continue

            visited.add(node)

            if node == b:
                return (cost, path)

            for neighbor in self.neighbors(node):
                if neighbor not in visited:
                    new_cost = cost + self.edges.get((node, neighbor), float('inf'))
                    new_path = path + [neighbor]
                    heapq.heappush(priority_queue, (new_cost, new_path))

        return None

    def has_cycle(self):
        visited = set()
        rec_stack = set()

        def dfs(node):
            visited.add(node)
